<section class="stat-grid cash-stats"><article class="stat-card"><span class="stat-label">Solde courant</span><strong><?= money($summary['solde']) ?></strong><span class="stat-note">entrées moins sorties</span></article><article class="stat-card"><span class="stat-label">Opérations</span><strong><?= e($summary['operations']) ?></strong><span class="stat-note">mouvements de caisse</span></article></section><div class="cash-layout"><section class="panel form-panel"><p class="eyebrow">CAISSE</p><h2>Nouvelle opération</h2><form method="post" action="<?= BASE_URL ?>/index.php?page=caisse-save" class="data-form"><label>Type d’opération<select name="type_operation"><option value="ENTREE">Entrée d’argent</option><option value="SORTIE">Sortie / dépense</option></select></label><label>Montant<input required type="number" min="0.01" step="0.01" name="montant"></label><label>Motif<textarea required name="motif" rows="3" placeholder="Ex. achat fournitures..." ></textarea></label><button class="button button-primary" type="submit">Enregistrer</button></form></section><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">JOURNAL DE CAISSE</p><h2>Opérations récentes</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Motif</th><th>Montant</th></tr></thead><tbody><?php foreach ($operations as $operation): ?><tr><td><?= date('d/m/Y H:i', strtotime($operation['date_operation'])) ?></td><td><span class="type-label <?= strtolower($operation['type_operation']) ?>"><?= e($operation['type_operation']) ?></span></td><td><?= e($operation['motif']) ?></td><td><strong><?= $operation['type_operation'] === 'SORTIE' ? '-' : '+' ?><?= money($operation['montant']) ?></strong></td></tr><?php endforeach; ?></tbody></table></div></section></div>
